declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';require __DIR__.'/../Yii2/Yii2AuthFixture.php';
use FMonitor2\Tests\Yii2\Yii2AuthFixture;use FMonitor2\Otiz\OtizSettlementV2;
$f=new Yii2AuthFixture(dirname(__DIR__,2));$db=null;
try{
 $f->setPermission('otiz.manage');$e=$f->environment();$db=new yii\db\Connection(['dsn'=>'mysql:host='.$e['FMONITOR_DB_HOST'].';port='.$e['FMONITOR_DB_PORT'].';dbname='.$f->database,'username'=>$e['FMONITOR_DB_USER'],'password'=>$e['FMONITOR_DB_PASSWORD'],'charset'=>'utf8mb4']);$db->open();$p=$f->prefix;$o=new OtizSettlementV2($db,$p,static fn()=>'2026-10-30T09:00:00+03:00',static fn()=>'allow');$n=1;$op=static function()use(&$n):string{return sprintf('30303030-3030-4303-8303-%012d',$n++);};
 $input=['reportDate'=>'2026-10-30','recipientPolicyVersion'=>'reserved-shares-v1','objects'=>[]];foreach([[4512,1000000,[['101',50],['202',50]]],[4513,2000000,[['101',40],['303',60]]]]as[$oid,$gross,$crew]){$rec=[];foreach($crew as[$id,$weight])$rec[]=['employeeId'=>$id,'tabNumber'=>$id,'name'=>'Монтажник '.$id,'employment'=>'employed','weight'=>$weight];$input['objects'][]=['objectId'=>$oid,'regnumber'=>'OBJ-'.$oid,'fundCents'=>$gross,'entitlements'=>[['sourceKind'=>'fixture','sourceId'=>'scoped-'.$oid,'sourceRevision'=>'1','kind'=>'progress','recognitionDate'=>'2026-10-20','grossCents'=>$gross]],'recipients'=>$rec];}
 $draft=$o->createDraft(9101,$input,$op());$id=$draft['calculationId'];
 assertSameValue(true,method_exists($o,'saveObjectDecision')&&method_exists($o,'previewObjectDecision'),'INTENDED_RED: exact object+installer decision seams required');
