 $amounts=static function(array$c):array{$out=[];foreach($c['recipients']as$r)$out[$r['objectId'].'|'.$r['employeeId']]=[(int)$r['amountCents'],(int)($r['reservedCents']??0)];return$out;};
 $before=$fingerprint();$preview=$o->previewObjectDecision(9101,$id,1,4512,'101','do_not_pay','Проверка ИБ');assertSameValue($before,$fingerprint(),'preview read-only');$expected=['4512|101'=>[0,500000],'4512|202'=>[500000,0],'4513|101'=>[800000,0],'4513|303'=>[1200000,0]];assertSameValue($expected,$amounts($preview),'reserve only exact pair, coworkers and other object unchanged');
 $denied=false;try{$o->saveObjectDecision(9101,$id,1,4512,'101','do_not_pay','',$op());}catch(DomainException){$denied=true;}assertSameValue(true,$denied,'reason mandatory');assertSameValue($before,$fingerprint(),'missing reason no writes');
 $saveOp=$op();$saved=$o->saveObjectDecision(9101,$id,1,4512,'101','do_not_pay','Проверка ИБ',$saveOp);assertSameValue($expected,$amounts($saved),'saved scope exact');assertSameValue(2,$saved['revision'],'one new revision');assertSameValue($saved,$o->saveObjectDecision(9101,$id,1,4512,'101','do_not_pay','Проверка ИБ',$saveOp),'exact operation replay');
 $before=$fingerprint();$conflicted=false;try{$o->saveObjectDecision(9101,$id,1,4513,'101','do_not_pay','Проверка ИБ',$saveOp);}catch(DomainException$e){$conflicted=$e->getMessage()==='OPERATION_CONFLICT';}assertSameValue(true,$conflicted,'operation id cannot be reused on another object');assertSameValue($before,$fingerprint(),'conflicting operation changes no facts');
 $before=$fingerprint();foreach([[1,4513,'101','Проверка'],[2,4512,'303','Нет такого участника']]as[$rev,$object,$employee,$reason]){$failed=false;try{$o->saveObjectDecision(9101,$id,$rev,$object,$employee,'do_not_pay',$reason,$op());}catch(DomainException){$failed=true;}assertSameValue(true,$failed,'stale or wrong-object recipient rejected');assertSameValue($before,$fingerprint(),'rejected scope no facts');}
 $accepted=$o->accept(9101,$id,2,$op());$paid=$o->markPaid(9101,$id,$accepted['revision'],'2026-10-30',$op());assertSameValue(2500000,$paid['paidCents'],'only withheld pair excluded from payment');assertSameValue(500000,$o->read($id)['remainingReservedCents'],'reserve retained after coworkers/other objects paid');
 $before=$fingerprint();$blocked=false;try{$o->saveObjectDecision(9101,$id,$accepted['revision'],4513,'101','do_not_pay','После выплаты',$op());}catch(DomainException){$blocked=true;}assertSameValue(true,$blocked,'paid calculation cannot be rewritten');assertSameValue($before,$fingerprint(),'paid facts unchanged');
 foreach($input['objects']as&$object)$object['entitlements'][0]['sourceId'].='-legacy';unset($object);$legacy=$o->createDraft(9101,$input,$op());$legacy=$o->saveDecision(9101,$legacy['calculationId'],1,'101','do_not_pay','Историческое решение по всему расчёту',$op());assertSameValue([0,800000],$amounts($legacy)['4513|101'],'legacy NULL scope remains global');
 $legacyRows=$db->createCommand("SELECT employee_id,object_id,decision,reason,active FROM `{$p}fm2_otiz_payment_decisions` WHERE calculation_id=:id",[':id'=>$legacy['calculationId']])->queryAll();assertSameValue(null,$legacyRows[0]['object_id'],'legacy decision encoded NULL');
 $override=$o->saveObjectDecision(9101,$legacy['calculationId'],2,4513,'101','pay','Разбирательство по этому объекту завершено',$op());assertSameValue([0,500000],$amounts($override)['4512|101'],'legacy scope retained on other object');assertSameValue([800000,0],$amounts($override)['4513|101'],'exact pair override explicit');assertSameValue('1',(string)$db->createCommand("SELECT active FROM `{$p}fm2_otiz_payment_decisions` WHERE calculation_id=:id AND object_id IS NULL",[':id'=>$legacy['calculationId']])->queryScalar(),'legacy fact remains active and intact');
 foreach($input['objects']as&$object)$object['entitlements'][0]['sourceId'].='-replacement';unset($object);$repl=$o->createDraft(9101,$input,$op());$repl=$o->saveObjectDecision(9101,$repl['calculationId'],1,4512,'101','do_not_pay','Только первый объект',$op());$repl=$o->accept(9101,$repl['calculationId'],2,$op());
 $replacement=$o->createReplacementDraft(9101,$repl['calculationId'],$repl['revision'],$input,'Замена с сохранением области решения',$op());
 $scope=$db->createCommand("SELECT object_id FROM `{$p}fm2_otiz_payment_decisions` WHERE calculation_id=:id AND active=1",[':id'=>$replacement['calculationId']])->queryColumn();assertSameValue(['4512'],array_map('strval',$scope),'INTENDED_RED replacement must preserve object scope instead of global NULL');
 $replacementPreview=$o->previewObjectDecision(9101,$replacement['calculationId'],$replacement['revision'],4513,'303','pay','Без изменения');assertSameValue($expected,$amounts($replacementPreview),'replacement preview cannot spread exclusion to another object');
 echo "PASS: object-scoped decision reservation/preview/replay/stale/payment/history compatibility\n";
}finally{if($db)$db->close();$f->close();}
